Lemma gvlit_facts : forall m A L, In (A, L) GVLITS -> mem_inv bsegs m -> ACONST m ->
  bytes_at bsegs m A (map b8 (L ++ 0 :: [])) /\ Forall (fun c => 0 < c < 256) L
  /\ accessible m A (Z.of_nat (length L) + 1) /\ shvis m A (A + Z.of_nat (length L) + 1)
  /\ in_app_mem A (A + Z.of_nat (length L) + 1)
  /\ AIMG_LO + 64 <= A /\ A + Z.of_nat (length L) + 1 + 64 <= AIMG_TOP.
