Lemma acanary_transport : forall W m m', acanary m -> munch W m m' -> wmono bsegs m m' -> disjoint_from W A_STKCHK_GUARD 8 -> acanary m'.
Proof.
  intros W m m' [can CN] MU WM DJ. exists can. eapply rw_cells_transport; [exact CN | exact MU | exact WM | exact DJ].
Qed.

