  lazymatch goal with ST' : stk _ _ _ (bv_unsigned ?sp + -64), FR' : rw_cells _ _ (bv_unsigned ?sp' + -64) _ |- _ =>
    release_frame FR' ST' (bv_unsigned sp) end;
